package com.bank.returns;

import java.util.logging.Logger;

public class ReturnsAnalyzer {

    private static final Logger log = Logger.getLogger(ReturnsAnalyzer.class.getName());

    public int maxProduct(int[] nums) {
        int max = nums[0], min = nums[0], answer = nums[0];
        for (int i = 1; i < nums.length; i++) {
            int x = nums[i];
            int oldMax = max, oldMin = min;            // capture before overwriting
            max = Math.max(x, Math.max(x * oldMax, x * oldMin)); // negative may swap
            min = Math.min(x, Math.min(x * oldMax, x * oldMin));
            answer = Math.max(answer, max);            // track global best
        }
        final int result = answer;
        log.info(() -> "Maximum product subarray = " + result);
        return result;
    }
}
