package com.bank.returns;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class MaxProductDemo {

    private static final Logger log = Logger.getLogger(MaxProductDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Returns Analyzer (Maximum Product Subarray)");
        ReturnsAnalyzer analyzer = new ReturnsAnalyzer();
        log.info("{2,3,-2,4} → " + analyzer.maxProduct(new int[]{2, 3, -2, 4}));   // 6
        log.info("{-2,0,-1} → " + analyzer.maxProduct(new int[]{-2, 0, -1}));       // 0
    }
}
